"""Page Cartons & fournitures : vente de cartons, emballages et matériel (rubrique reprise du site d'origine CODEM)."""
import build as b
from build import t,url,link,img,eyebrow,PHONE,PHONE_HREF,label

PARTICULIERS=[
 ('Cartons standard et cartons livres','Standard and book boxes','Des formats adaptés au poids : petits cartons pour les livres et la vaisselle lourde, plus grands pour le linge et les objets légers.','Sizes matched to weight: small boxes for books and heavy crockery, larger ones for linen and light items.'),
 ('Cartons à séparations pour verres','Divided boxes for glasses','Des compartiments pour caler verres et bouteilles un par un, sans contact entre eux.','Compartments that hold glasses and bottles one by one, with no contact between them.'),
 ('Cartons à linge','Linen boxes','Pour le linge de maison, les couettes et les vêtements pliés.','For household linen, duvets and folded clothes.'),
 ('Penderies','Wardrobe boxes','Vos vêtements voyagent sur cintres et arrivent prêts à ranger, sans être froissés.','Your clothes travel on hangers and arrive ready to put away, uncreased.'),
 ('Housses matelas et sommiers','Mattress and base covers','Des housses de protection contre la poussière, les frottements et l’humidité pendant le transport.','Covers that protect against dust, rubbing and damp in transit.'),
 ('Couvertures de protection','Protective blankets','Les couvertures utilisées par nos déménageurs pour envelopper les meubles et éviter les rayures.','The blankets our movers use to wrap furniture and prevent scratches.'),
 ('Papier bulle et rouleaux de mousse','Bubble wrap and foam rolls','Pour la vaisselle, les cadres, les miroirs et tous les objets fragiles.','For crockery, frames, mirrors and every fragile item.'),
 ('Accessoires de calage','Packing fillers','De quoi remplir les vides dans les cartons pour que rien ne bouge pendant le trajet.','Fillers for the gaps in boxes so nothing moves on the road.'),
]
ENTREPRISES=[
 ('Cartons archives','Archive boxes','Pour transférer dossiers et documents dans l’ordre, étiquetés par service.','To move files and documents in order, labelled by department.'),
 ('Cartons longs et formats hors normes','Long and oversized boxes','Pour les plans, les affiches, les tubes et les objets aux dimensions particulières.','For plans, posters, tubes and items with unusual dimensions.'),
 ('Cartons palettisables','Palletisable boxes','Des cartons conçus pour être chargés sur palette lors des transferts volumineux.','Boxes designed to be loaded on pallets for large relocations.'),
]

def _cards(items,start=1):
 return ''.join(f'<article class="loc-card"><span class="eyebrow">{str(i+start).zfill(2)}</span><h3>{t(a,c)}</h3><p>{t(d,e)}</p></article>' for i,(a,c,d,e) in enumerate(items))

def page():
 dq=url('devis')+'?detail=1&prestation=cartons'
 body=f'''
<section class="page-intro loc-intro"><div class="wrap split"><div>{eyebrow("Vente de fournitures","Packing supplies")}<h1>{t("Cartons, emballages<br><em>et matériel de protection.</em>","Boxes, packing<br><em>and protective materials.</em>")}</h1><p class="lead">{t("Vous préférez emballer vous-même ? CODEM vend les cartons, emballages et fournitures utilisés par ses déménageurs, pour les particuliers comme pour les entreprises.","Prefer to pack yourself? CODEM sells the boxes, packing and supplies its own movers use, for households and businesses.")}</p><div class="actions"><a class="btn btn-cta" href="{dq}">{t("Commander mes fournitures","Order my supplies")}</a><a class="loc-phone" href="{PHONE_HREF}">{PHONE}<small class="nosurtax">{t("Appel non surtaxé","Standard call rate")}</small></a></div><p class="title-promise">{t("Quantités conseillées selon votre volume · Tarifs sur demande","Quantities advised for your volume · Prices on request")}</p></div><div class="mascot-host">{b.mascot("couverture","hero-side-mascot",230)}<div class="image-wrap">{img("particulier-emballage",t("Déménageur CODEM emballant des objets dans un carton","CODEM mover packing items into a box"),eager=True)}</div></div></div></section>
<section class="section band-sand"><div class="wrap"><div class="section-heading"><div>{eyebrow("Pour les particuliers","For households")}<h2>{t("Tout pour emballer<br><em>sans rien oublier.</em>","Everything to pack<br><em>without missing a thing.</em>")}</h2></div></div><div class="loc-grid supply-grid">{_cards(PARTICULIERS)}</div></div></section>
<section class="section band-ivory"><div class="wrap split loc-split"><div>{eyebrow("Pour les entreprises","For businesses")}<h2>{t("Archives et transferts<br><em>de bureaux.</em>","Records and<br><em>office moves.</em>")}</h2><p class="lead">{t("Pour un transfert d’entreprise, les cartons sont choisis selon vos dossiers, vos équipements et l’organisation du chargement.","For a business relocation, boxes are chosen to suit your files, equipment and loading plan.")}</p>{link("entreprises",t("Découvrir le transfert d’entreprise","Explore business relocation"),"text-link")}</div><div class="loc-grid one-col">{_cards(ENTREPRISES,len(PARTICULIERS)+1)}</div></div></section>
<section class="section band-glacier"><div class="wrap split loc-split"><div><div class="image-wrap">{img("particulier-housse",t("Matelas protégé par une housse avant le transport","Mattress protected with a cover before transport"))}</div></div><div>{eyebrow("Comment commander","How to order")}<h2>{t("Les bonnes quantités,<br><em>du premier coup.</em>","The right quantities,<br><em>first time.</em>")}</h2><ol class="supply-steps"><li><strong>{t("Estimez votre volume","Estimate your volume")}</strong><span>{t("Avec notre calculateur pièce par pièce, ou lors de la visite de votre conseiller.","With our room-by-room calculator, or during your adviser’s visit.")}</span></li><li><strong>{t("Indiquez vos besoins","Tell us what you need")}</strong><span>{t("Cochez « Cartons » dans votre demande de devis, ou appelez-nous.","Tick “Boxes” in your quote request, or call us.")}</span></li><li><strong>{t("Recevez une proposition","Get a proposal")}</strong><span>{t("Votre conseiller vous indique les quantités adaptées, les tarifs et les modalités de retrait ou de livraison.","Your adviser confirms suitable quantities, prices and collection or delivery arrangements.")}</span></li></ol><div class="actions"><a class="btn btn-cta" href="{dq}">{t("Commander mes fournitures","Order my supplies")}</a><a class="text-link" href="{url("conseils")}#volume">{t("Calculer mon volume","Calculate my volume")}</a></div></div></div></section>
<section class="section band-ivory"><div class="wrap split loc-split"><div>{eyebrow("Ou laissez-nous faire","Or leave it to us")}<h2>{t("L’emballage<br><em>par nos déménageurs.</em>","Packing<br><em>by our movers.</em>")}</h2></div><div><p class="lead">{t("Dès la formule Confort, nos déménageurs fournissent les emballages et emballent vos objets fragiles. Avec Confort plus et Grand Confort, ils emballent aussi le non-fragile. Avec Self et Self plus, vous emballez vous-même, et nos fournitures sont à votre disposition.","From the Confort package, our movers supply the packing and wrap your fragile items. With Confort plus and Grand Confort, they also pack non-fragile items. With Self and Self plus, you pack yourself, and our supplies are available to you.")}</p>{link("formules",t("Comparer les formules","Compare packages"),"btn outline")}</div></div></section>'''+b.cta()
 desc=t('Cartons, penderies, housses, papier bulle, cartons archives et palettisables : CODEM vend les fournitures de déménagement à Nogent-sur-Marne, pour particuliers et entreprises.','Boxes, wardrobe boxes, covers, bubble wrap, archive and palletisable boxes: CODEM sells moving supplies in Nogent-sur-Marne for households and businesses.')
 return body,desc

def write_all():
 body,desc=page();b.write('cartons',body,desc)

def strip():
 """Bandeau de rappel sur la page Particuliers."""
 return f'<section class="section band-sand supply-strip"><div class="wrap split loc-split"><div>{eyebrow("Vous emballez vous-même ?","Packing yourself?")}<h2>{t("Cartons, penderies,<br><em>papier bulle et housses.</em>","Boxes, wardrobe boxes,<br><em>bubble wrap and covers.</em>")}</h2></div><div><p class="lead">{t("CODEM vend les fournitures utilisées par ses déménageurs, en quantités conseillées selon votre volume.","CODEM sells the supplies its own movers use, in quantities advised for your volume.")}</p><div class="actions">{link("cartons",t("Voir les fournitures","See the supplies"),"btn outline")}</div></div></div></section>'
